    """Best-effort conversion of an options-like object into a plain dict."""
    if opts is None:
        return {}
    if is_dataclass(opts):
        return dict(asdict(opts))
    if isinstance(opts, Mapping):
        return dict(opts)
    to_dict = getattr(opts, "to_dict", None)
    if callable(to_dict):
        try:
            return dict(to_dict())
