            return None

def get_counts(self, shots: int | None = None) -> dict[str, int]:
        probs = self.get_probabilities()
        def dyadic_k(p: float, tol=1e-12, kmax=60) -> int | None:
            if p in (0.0, 1.0):
                return 0
            for k in range(kmax + 1):
                m = round(p * (1 << k))
                if abs(p - m / float(1 << k)) <= tol:
                    return k
            return None
        ks = []
        for p in probs.values():
            k = dyadic_k(p)
            if k is None:
